import { manual, ask, kg } from adapters
import { kg_cred } from credentials
runs = manual()
graph = kg(credentials: kg_cred)
qa = ask()

movement m(go: <runs-[:Invocation]->>) {
  a = write qa-[:Check]-> { Prompt: "Ship it?" }
  cb = callback({ write a-[:Response]-> { Answer: TRUE } })
  write graph-[:log]-> { text: cb.id }
}
listen to runs {} fire m

import { manual, kg } from adapters
import { kg_cred } from credentials
runs = manual()
graph = kg(credentials: kg_cred)

movement m(go: <runs-[:Invocation]->>) {
  cb = callback()
  c = await FIRST(cb-[:Called]->)
  write graph-[:log]-> { text: "continued" }
}
listen to runs {} fire m

import { slack, attio, kg } from adapters
import { dev_slack, acme_main } from credentials

inbox = slack(credentials: dev_slack)
crm   = attio(credentials: acme_main)
graph = kg()

movement intake(msg: <inbox-[:message]->>) {
  r = await race([
    () => {
      await sleep(30d)
      made = write crm-[:companies]-> {
        unique by (`name`)
        name: "Acme"
      }
      return made.externalId
    },
    () => { await sleep(30d) },
  ])
  if AT(r, 0) != null {
    write crm-[:companies]-> {
      unique by (`name`)
      name: "won-${AT(r, 0)}"
    }
  }
}

