inbox = slack(credentials: dev_slack)
crm   = attio(credentials: acme_main)
graph = kg()

movement m(msg: <inbox-[:message]->>) {
  if msg IS <inbox-[:message]->> {
    write crm-[:companies]-> {
      unique by (`name`)
      name: msg.`user`
    }
  } else {
    write inbox-[:messages]-> {
      channel: "#skipped"
      text:    "no match"
    }
  }
}

