graph = kg()

movement m(msg: <inbox-[:message]->>) {
  fr = write graph-[:funding_round]-> {
    unique by (`company`)
    company: msg.`subject`
  }
  inv = write graph-[:investor]-> {
    unique by (`name`)
    name: msg.`text`
  }
  write (fr-[:participants]->, inv-[:participations]->) {
    unique by (fr AND inv)
    name: msg.`text`
  }
}

